function pageSettings(input) {
  const rows = input?.rows ?? 25;       // 0 survives — only nullish gets the default
  const label = input?.label ?? "results";
  const owner = input?.owner?.name ?? "anonymous";
  return `${rows} ${label} — ${owner}`;
}

console.log(pageSettings({ rows: 0, label: "hits", owner: { name: "Ada" } }));
// "0 hits — Ada"
console.log(pageSettings(null));
// "25 results — anonymous"
console.log(pageSettings({ rows: 50 }));
// "50 results — anonymous"

