function pageSettings(input) {
  const rows = input.rows || 25;        // ← erases a legitimate 0
  const label = input.label || "results";
  const owner = input.owner.name;       // ← crashes when owner (or input) is missing
  return `${rows} ${label} — ${owner}`;
}

console.log(pageSettings({ rows: 0, label: "hits", owner: { name: "Ada" } }));
console.log(pageSettings(null));
